package android.preference;import android.content.Context;public class Preference{String key;CharSequence title,summary;public Preference(Context c){}public String getKey(){return key;}public void setKey(String k){key=k;}public void setTitle(CharSequence t){title=t;}public CharSequence getTitle(){return title;}public void setSummary(CharSequence s){summary=s;}public CharSequence getSummary(){return summary;}}
